// Helper functions
export function getBlogsByToolSlug(toolSlug: string): BlogPost[] {
    return ALL_BLOG_POSTS.filter(b => b.toolSlug === toolSlug)
}

export function getBlogBySlug(slug: string): BlogPost | undefined {
    return ALL_BLOG_POSTS.find(b => b.slug === slug)
}

export function getAllBlogSlugs(): string[] {
    return ALL_BLOG_POSTS.map(b => b.slug)
}

export function getRelatedBlogs(slug: string, limit = 5): BlogPost[] {
    const blog = getBlogBySlug(slug)
    if (!blog) return []
    return ALL_BLOG_POSTS.filter(b => b.toolSlug === blog.toolSlug && b.slug !== slug).slice(0, limit)
}
